+fn write_cycle(buffer: &mut String, cycle: &[EcoString]) {
+    buffer.push_str(
+        "
+    ┌─────┐\n",
+    );
+    for (index, name) in cycle.iter().enumerate() {
+        if index != 0 {
+            buffer.push_str("    │     ↓\n");
+        }
+        buffer.push_str("    │     ");
+        buffer.push_str(name);
+        buffer.push('\n');
+    }
+    buffer.push_str("    └─────┘\n");
+}
