+/// Given a constants, this will change its type into the given one, turning
+/// the constant into an `Invalid` one if necessary.
+///
+fn invalid_with_annotated_type(constant: TypedConstant, new_type: Arc<Type>) -> TypedConstant {
+    // In case the types cannot be unified we change the inferred we
+    // return a constant where the type matches the annotated one.
+    // This can help minimise false positive later on!
+    match constant {
+        // For simple variants that don't carry their own type we
+        // replace them with an invalid constant with the same
+        // location and the new annotated type.
+        Constant::Int { location, .. }
+        | Constant::Float { location, .. }
+        | Constant::String { location, .. }
+        | Constant::BitArray { location, .. }
+        | Constant::StringConcatenation { location, .. } => TypedConstant::Invalid {
+            location,
+            type_: new_type,
+            extra_information: None,
+        },
+
+        // Todos should never result in type errors like this one, but just to
+        // be safe rather than panicking we replace the type with the new one.
+        Constant::Todo {
+            location, message, ..
+        } => TypedConstant::Todo {
+            location,
+            type_: new_type,
+            message,
+        },
+
+        // In all other cases we don't want to lose information on
+        // the actual structure of the invalid expression. So we just
+        // replace the type with the annotated one.
+        Constant::Invalid {
+            location,
+            type_: _,
+            extra_information,
+        } => Constant::Invalid {
+            location,
+            type_: new_type,
+            extra_information,
+        },
+
+        Constant::Tuple {
+            location,
+            elements,
+            type_: _,
+        } => Constant::Tuple {
+            location,
+            elements,
+            type_: new_type,
+        },
+
+        Constant::List {
+            location,
+            elements,
+            type_: _,
+            tail,
+        } => Constant::List {
+            location,
+            elements,
+            type_: new_type,
+            tail,
+        },
+
+        Constant::Record {
+            location,
+            module,
+            name,
+            arguments,
+            type_: _,
+            field_map,
+            record_constructor,
+        } => Constant::Record {
+            location,
+            module,
+            name,
+            arguments,
+            type_: new_type,
+            field_map,
+            record_constructor,
+        },
+
+        Constant::RecordUpdate {
+            location,
+            constructor_location,
+            module,
+            name,
+            record,
+            arguments,
+            type_: _,
+            field_map,
+        } => Constant::RecordUpdate {
+            location,
+            constructor_location,
+            module,
+            name,
+            record,
+            arguments,
+            type_: new_type,
+            field_map,
+        },
+
+        Constant::Var {
+            location,
+            module,
+            name,
+            constructor,
+            type_: _,
+        } => Constant::Var {
+            location,
+            module,
+            name,
+            constructor,
+            type_: new_type,
+        },
+    }
+}
